{
  "assessment": "As the new Head of Government, our economic fundamentals are stable with modest growth at 1.4% and manageable inflation at 3.2%. However, our budget deficit at 2.5% of GDP and low military spending relative to our strategic environment (1.9%) warrant attention. To secure our long-term prosperity and security in the Indo-Pacific, we should slightly boost infrastructure investment, maintain our robust democratic and diplomatic alliances, and ensure our economic policies foster higher growth.",
  "directives": [
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "order": "Increase infrastructure investment by 0.5% of GDP to boost productivity and growth."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 2.1,
      "sub": "military",
      "order": "Incrementally raise military spending to 2.1% of GDP to address regional security readiness."
    }
  ],
  "cables": [
    {
      "to": "USA",
      "private": true,
      "text": "Reaffirming our steadfast commitment to the AUKUS partnership and our enduring alliance for regional security."
    },
    {
      "to": "NZL",
      "private": true,
      "text": "Warm regards to our closest neighbour and treaty ally. Looking forward to continued close cooperation."
    }
  ],
  "public_statement": "My government is committed to fostering sustainable economic growth, investing in our national infrastructure, and maintaining strong, cooperative relationships with our international partners to secure a prosperous future for all Australians.",
  "standing_orders": [
    {
      "when": "inflation_above:4.0",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 0.25,
        "sub": "",
        "order": "Raise the policy rate by 0.25 percentage points to cool inflation."
      }
    }
  ],
  "detailed_report": "economy"
}
